START TRANSACTION;
ALTER TABLE "Users" ADD "IsPlatformAdmin" boolean NOT NULL DEFAULT FALSE;

CREATE TABLE "RoleDefinitions" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" text,
    "Code" text,
    "IsSystemPreset" boolean NOT NULL,
    "CompanyId" bigint,
    "Deleted" boolean NOT NULL,
    "LogDbEntryId" bigint,
    CONSTRAINT "PK_RoleDefinitions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RoleDefinitions_Companies_CompanyId" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_RoleDefinitions_LogDbEntries_LogDbEntryId" FOREIGN KEY ("LogDbEntryId") REFERENCES "LogDbEntries" ("Id")
);

CREATE TABLE "RoleAccessOverrides" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "RoleDefinitionId" bigint NOT NULL,
    "Code" integer NOT NULL,
    "Allowed" boolean NOT NULL,
    "LogDbEntryId" bigint,
    CONSTRAINT "PK_RoleAccessOverrides" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RoleAccessOverrides_LogDbEntries_LogDbEntryId" FOREIGN KEY ("LogDbEntryId") REFERENCES "LogDbEntries" ("Id"),
    CONSTRAINT "FK_RoleAccessOverrides_RoleDefinitions_RoleDefinitionId" FOREIGN KEY ("RoleDefinitionId") REFERENCES "RoleDefinitions" ("Id") ON DELETE CASCADE
);

CREATE TABLE "RoleModuleGrants" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "RoleDefinitionId" bigint NOT NULL,
    "Module" integer NOT NULL,
    "Level" integer NOT NULL,
    "LogDbEntryId" bigint,
    CONSTRAINT "PK_RoleModuleGrants" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RoleModuleGrants_LogDbEntries_LogDbEntryId" FOREIGN KEY ("LogDbEntryId") REFERENCES "LogDbEntries" ("Id"),
    CONSTRAINT "FK_RoleModuleGrants_RoleDefinitions_RoleDefinitionId" FOREIGN KEY ("RoleDefinitionId") REFERENCES "RoleDefinitions" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserCompanyRoles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "CompanyId" bigint,
    "RoleDefinitionId" bigint NOT NULL,
    "LogDbEntryId" bigint,
    CONSTRAINT "PK_UserCompanyRoles" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserCompanyRoles_Companies_CompanyId" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UserCompanyRoles_LogDbEntries_LogDbEntryId" FOREIGN KEY ("LogDbEntryId") REFERENCES "LogDbEntries" ("Id"),
    CONSTRAINT "FK_UserCompanyRoles_RoleDefinitions_RoleDefinitionId" FOREIGN KEY ("RoleDefinitionId") REFERENCES "RoleDefinitions" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UserCompanyRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_RoleAccessOverrides_LogDbEntryId" ON "RoleAccessOverrides" ("LogDbEntryId");

CREATE UNIQUE INDEX "IX_RoleAccessOverrides_RoleDefinitionId_Code" ON "RoleAccessOverrides" ("RoleDefinitionId", "Code");

CREATE UNIQUE INDEX "IX_RoleDefinitions_Code" ON "RoleDefinitions" ("Code") WHERE "CompanyId" IS NULL AND "Code" <> '' AND "Deleted" = false;

CREATE INDEX "IX_RoleDefinitions_CompanyId" ON "RoleDefinitions" ("CompanyId");

CREATE INDEX "IX_RoleDefinitions_LogDbEntryId" ON "RoleDefinitions" ("LogDbEntryId");

CREATE INDEX "IX_RoleModuleGrants_LogDbEntryId" ON "RoleModuleGrants" ("LogDbEntryId");

CREATE UNIQUE INDEX "IX_RoleModuleGrants_RoleDefinitionId_Module" ON "RoleModuleGrants" ("RoleDefinitionId", "Module");

CREATE INDEX "IX_UserCompanyRoles_CompanyId" ON "UserCompanyRoles" ("CompanyId");

CREATE INDEX "IX_UserCompanyRoles_LogDbEntryId" ON "UserCompanyRoles" ("LogDbEntryId");

CREATE INDEX "IX_UserCompanyRoles_RoleDefinitionId" ON "UserCompanyRoles" ("RoleDefinitionId");

CREATE UNIQUE INDEX "IX_UserCompanyRoles_UserId_CompanyId_RoleDefinitionId" ON "UserCompanyRoles" ("UserId", "CompanyId", "RoleDefinitionId");

CREATE UNIQUE INDEX "IX_UserCompanyRoles_UserId_RoleDefinitionId" ON "UserCompanyRoles" ("UserId", "RoleDefinitionId") WHERE "CompanyId" IS NULL;

