START TRANSACTION;
ALTER TABLE "TriggerRules" ADD "Priority" integer NOT NULL DEFAULT 0;

CREATE TABLE "EventLogEntries" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CompanyId" bigint NOT NULL,
    "CompanyName" text,
    "TriggerRuleId" bigint,
    "Priority" integer NOT NULL,
    "Title" text,
    "Body" text,
    "DriverId" bigint,
    "Deleted" boolean NOT NULL,
    "LegacySource" integer NOT NULL,
    "LegacyId" bigint,
    "CreatedTime" timestamp with time zone NOT NULL,
    "ModifiedTime" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EventLogEntries" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EventLogEntries_Companies_CompanyId" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_EventLogEntries_TriggerRules_TriggerRuleId" FOREIGN KEY ("TriggerRuleId") REFERENCES "TriggerRules" ("Id") ON DELETE SET NULL
);

CREATE TABLE "Notifications" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint NOT NULL,
    "CompanyId" bigint,
    "CompanyName" text,
    "Module" integer NOT NULL,
    "TemplateKey" text,
    "ParamsJson" text,
    "Priority" integer NOT NULL,
    "RequiresAction" boolean NOT NULL,
    "Title" text,
    "Body" text,
    "EntityType" text,
    "EntityId" bigint,
    "GroupKey" text,
    "IsRead" boolean NOT NULL,
    "ReadAt" timestamp with time zone,
    "Deleted" boolean NOT NULL,
    "LegacySource" integer NOT NULL,
    "LegacyId" bigint,
    "CreatedTime" timestamp with time zone NOT NULL,
    "ModifiedTime" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Notifications" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Notifications_Companies_CompanyId" FOREIGN KEY ("CompanyId") REFERENCES "Companies" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Notifications_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "EventLogReads" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "EventLogEntryId" bigint NOT NULL,
    "UserId" bigint NOT NULL,
    "ReadAt" timestamp with time zone,
    "Kind" integer NOT NULL,
    "CreatedTime" timestamp with time zone NOT NULL,
    "ModifiedTime" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_EventLogReads" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EventLogReads_EventLogEntries_EventLogEntryId" FOREIGN KEY ("EventLogEntryId") REFERENCES "EventLogEntries" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_EventLogReads_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_EventLogEntries_Feed" ON "EventLogEntries" ("CompanyId", "CreatedTime");

CREATE INDEX "IX_EventLogEntries_Priority" ON "EventLogEntries" ("CompanyId", "Priority", "CreatedTime");

CREATE INDEX "IX_EventLogEntries_TriggerRuleId" ON "EventLogEntries" ("TriggerRuleId");

CREATE UNIQUE INDEX "UQ_EventLogEntries_Legacy" ON "EventLogEntries" ("LegacySource", "LegacyId") WHERE "LegacyId" IS NOT NULL;

CREATE INDEX "IX_EventLogReads_UserEntry" ON "EventLogReads" ("UserId", "EventLogEntryId");

CREATE UNIQUE INDEX "UQ_EventLogReads_EntryUser" ON "EventLogReads" ("EventLogEntryId", "UserId");

CREATE INDEX "IX_Notifications_CompanyId" ON "Notifications" ("CompanyId");

CREATE INDEX "IX_Notifications_Unread" ON "Notifications" ("UserId", "CompanyId", "Module", "CreatedTime") WHERE NOT "IsRead" AND NOT "Deleted";

CREATE UNIQUE INDEX "UQ_Notifications_GroupKey" ON "Notifications" ("UserId", "GroupKey") WHERE "GroupKey" IS NOT NULL;

CREATE UNIQUE INDEX "UQ_Notifications_Legacy" ON "Notifications" ("LegacySource", "LegacyId") WHERE "LegacyId" IS NOT NULL;

